      oc_wrap_object(&oc_function_cell(c, code, env, 1, slots)->object);
  oc_protect(c, f);
  oc_value p = oc_new_object(c, oc_root_proto(c, 0), prototype_slots);
  oc_unprotect(c, 1);
  oc_set(c, f, 1, p);
  oc_set(c, p, 2, f);
