    return oc_bool(oc_strict_eq(a, b));
  if (op == 8)
    return oc_bool(!oc_strict_eq(a, b));
  if (op == 9)
    return oc_bool(oc_loose_eq(c, a, b));
  if (op == 10)
    return oc_bool(!oc_loose_eq(c, a, b));
  if (op == 21)
    return oc_truth(a) ? b : a;
  if (op == 22)
    return oc_truth(a) ? a : b;
  if (op == 23)
    return oc_nullish(a) ? b : a;
