  case 1:
    return oc_num(x + y);
  case 2:
    return oc_num(x - y);
  case 3:
    return oc_num(x * y);
  case 4:
    return oc_num(x / y);
  case 5:
    return oc_num(fmod(x, y));
  case 6:
    return oc_num(oc_pow(x, y));
  case 11:
    return oc_bool(x < y);
  case 12:
    return oc_bool(x <= y);
  case 13:
    return oc_bool(x > y);
  case 14:
    return oc_bool(x >= y);
  case 15:
    return oc_num(oc_i32(oc_u32(x) | oc_u32(y)));
  case 16:
    return oc_num(oc_i32(oc_u32(x) & oc_u32(y)));
  case 17:
    return oc_num(oc_i32(oc_u32(x) ^ oc_u32(y)));
  case 18:
    return oc_num(oc_i32(oc_u32(x) << (oc_u32(y) & 31)));
  case 19:
