  if (op == 4)
    return oc_num(x / y);
  if (op == 7 || op == 9)
    return oc_boolean(x == y);
  if (op == 8 || op == 10)
    return oc_boolean(x != y);
  if (op == 11)
    return oc_boolean(x < y);
  if (op == 12)
    return oc_boolean(x <= y);
  if (op == 13)
    return oc_boolean(x > y);
  if (op == 14)
    return oc_boolean(x >= y);
  if (op == 15)
    return oc_num(oc_i32(oc_u32(x) | oc_u32(y)));
  if (op == 16)
    return oc_num(oc_i32(oc_u32(x) & oc_u32(y)));
  if (op == 17)
    return oc_num(oc_i32(oc_u32(x) ^ oc_u32(y)));
  if (op == 18)
    return oc_num(oc_i32(oc_u32(x) << (oc_u32(y) & 31)));
  if (op == 19)
    return oc_num(oc_i32(oc_sar(oc_u32(x), oc_u32(y) & 31)));
  if (op == 20)
    return oc_num((double)(oc_u32(x) >> (oc_u32(y) & 31)));
